examples.template:
ScrollView {
    MonarchDiffViewer(
        before: [{{before.0}}, {{before.1}}, {{before.2}}, {{before.3}}, {{before.4}}],
        after: [{{after.0}}, {{after.1}}, {{after.2}}, {{after.3}}, {{after.4}}, {{after.5}}],
        beforeLabel: {{beforeLabel}},
        afterLabel: {{afterLabel}}
    )
    .padding()
}

examples.code:
ScrollView {
    MonarchDiffViewer(
        before: ["# Refund policy", "Refunds are available within 14 days.", "Contact support to start a refund.", "Refunds go back to the original payment method.", "Processing takes up to 10 days."],
        after: ["# Refund policy", "Refunds are available within 30 days.", "Contact support or use the billing page to start a refund.", "Refunds go back to the original payment method.", "Processing takes up to 5 business days.", "Partial refunds are possible for annual plans."],
        beforeLabel: "Version 3",
        afterLabel: "Version 4"
    )
    .padding()
}
